Node* closest_node = nullptr;
float min_distance = std::numeric_limits<float>::max();

for (const auto& node_pair : graph.nodes) {
    const Node* node = node_pair.second;
    // Skip nodes that are part of footway roads
    bool is_footway = false;
    for (const auto& way_id : node->way_ids) {
        const Way* way = graph.ways.at(way_id);
        if (way->type == Way::Type::FOOTWAY) {
            is_footway = true;
            break;
        }
    }
    if (is_footway) {
        continue;
    }

    float dx = node->x - x;
    float dy = node->y - y;
    float distance = dx * dx + dy * dy; // Squared distance to avoid sqrt

    if (distance < min_distance) {
        min_distance = distance;
        closest_node = const_cast<Node*>(node);
    }
}

return closest_node;
// END_CODE

